import java.sql.*;
import java.util.*;

public class Main {
    private static final String URL = "jdbc:h2:mem:toko;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";

    public static void main(String[] args) throws SQLException {
        try (Connection c = DriverManager.getConnection(URL, "sa", "")) {
            System.out.println("Koneksi terbuka: " + !c.isClosed());
            try (Statement st = c.createStatement()) {
                st.execute("CREATE TABLE kategori (id INT PRIMARY KEY, nama VARCHAR(50))");
                System.out.println(st.executeUpdate("INSERT INTO kategori VALUES (1, 'Alat tulis')"));
                st.execute("CREATE TABLE kategori (id INT PRIMARY KEY)");
            }
        } catch (SQLException e) {
            System.out.println("Gagal, kode SQLState " + e.getSQLState());
        }
    }
}

