cards.solution:
import java.sql.*;
import java.util.*;

public class Main {
    private static final String URL = "jdbc:h2:mem:toko;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";

    public static void main(String[] args) throws SQLException {
        Scanner in = new Scanner(System.in);
        try (Connection c = DriverManager.getConnection(URL, "sa", "");
             Statement st = c.createStatement()) {
            while (in.hasNextLine()) {
                String sql = in.nextLine().trim();
                try {
                    if (sql.toUpperCase().startsWith("CREATE")) {
                        st.execute(sql);
                        System.out.println("OK");
                    } else {
                        System.out.println(st.executeUpdate(sql) + " baris");
                    }
                } catch (SQLException e) {
                    System.out.println("Gagal: " + e.getSQLState());
                }
            }
        }
    }
}
